function intussusception(row,age){
 const infant=['u3m','3a5m','6a11m','1a'].includes(age),specific=row.kind==='int_recurrent'?['“Recorrente” significa que os sintomas voltaram após melhora ou redução anterior. Isso não autoriza observar em casa: vá agora ao pronto atendimento.','Episódios repetidos, idade maior ou apresentação atípica podem levar a equipe a investigar uma causa estrutural.']:row.kind==='int_refractory'?['“Refratária” pode significar que a redução não funcionou ou não pôde ser feita. Isso exige manejo hospitalar e avaliação cirúrgica; não tente outra medida em casa.','Falha de redução não se resolve com remédio por boca, massagem ou lavagem intestinal.']:['“Unilateral” não se aplica ao intestino e não define uma forma clínica. O segmento envolvido precisa ser identificado por imagem.','A palavra inadequada no cadastro não reduz a urgência nem permite presumir o lado ou a extensão.'];
 return [
  [...specific,'Intussuscepção é uma emergência em que um segmento do intestino entra dentro de outro. A criança pode parecer bem entre crises e ainda haver obstrução.',infant?'No bebê, crises de choro, palidez, pernas encolhidas, recusa de mamadas, vômitos ou moleza/sonolência são sinais importantes.':'Dor em crises, palidez, vômitos ou prostração são sinais importantes. Fezes com sangue e muco são tardias e podem não ocorrer.'],
  ['Não massageie a barriga, não tente reduzir o intestino e não faça enema ou lavagem intestinal.','Mantenha a criança acompanhada, anote início e frequência das crises e leve exames anteriores; não atrase a ida para observar outra crise.'],
  ['Não dê laxante, antidiarreico, antibiótico, analgésico extra ou remédio caseiro para tentar resolver. Redução guiada por imagem ou cirurgia só pode ser feita no hospital.'],
  ['Não ofereça comida ou bebida até avaliação da emergência, salvo orientação direta da equipe, pois podem ser necessários sedação, enema terapêutico ou cirurgia.'],
  ['A orientação já é ir imediatamente. Acione emergência se houver desmaio, dificuldade para acordar, respiração alterada, barriga muito distendida ou rígida, vômito verde, sangue nas fezes, palidez intensa ou sinais de choque.','Atraso pode levar a obstrução, perda de irrigação do intestino, perfuração, infecção abdominal e choque.'],
  ['A avaliação é agora, com ultrassom e equipe cirúrgica conforme o serviço. Após tratamento, volte imediatamente se dor em crises, vômitos, palidez ou prostração retornarem, especialmente nas primeiras 24–48 horas.']
 ];
}
function croup(age){
 const infant=['u3m','3a5m'].includes(age);
 return [
  [infant?'Crupe é incomum antes de 6 meses. Tosse ladrante, rouquidão ou barulho ao inspirar nessa idade precisam de avaliação pediátrica imediata.':'Crupe viral costuma causar tosse “de cachorro”, rouquidão e barulho ao puxar o ar, piorando à noite. Se a criança respira confortavelmente em repouso, está alerta e bebe líquidos, siga os cuidados e o plano da consulta.','Mantenha a criança calma e no colo ou na posição em que respira melhor. Choro e agitação podem piorar o estreitamento da via aérea.'],
  ['Ofereça ambiente calmo e ventilado. Não exponha a vapor quente: não há benefício comprovado e há risco de queimadura.','Observe a respiração com a criança em repouso. O volume do barulho sozinho não mede a gravidade; esforço para respirar, palidez, cansaço e estado de alerta são mais importantes.'],
  ['Use apenas o medicamento prescrito para este episódio. Não repita corticoide ou adrenalina nebulizada em casa por conta própria.','Antibiótico não trata crupe viral. Não dê codeína nem antitussivo para “cortar” a tosse; podem causar efeitos adversos e não resolvem o estreitamento.'],
  [age==='u3m'||age==='3a5m'||age==='6a11m'?'Mantenha leite materno ou fórmula em ofertas menores e frequentes, se a respiração permitir. Não force mamada durante esforço respiratório.':'Ofereça líquidos em pequenas quantidades e alimentação conforme aceitação; não force.','Recusa de líquidos, menos urina, boca seca, vômitos repetidos ou cansaço para beber exigem reavaliação.'],
  ['Estridor em repouso, costelas ou pescoço afundando, respiração muito rápida ou difícil, baba ou incapacidade de engolir, palidez intensa, lábios arroxeados, muita sonolência ou dificuldade para acordar: procure pronto atendimento imediatamente; em risco de vida, ligue 192.','Não examine a garganta à força nem deixe a criança deitada se isso piorar a respiração.'],
  ['Se recebeu adrenalina nebulizada, cumpra o período de observação definido pela equipe; não saia antes da liberação. Volte imediatamente se o estridor em repouso ou o esforço retornar.','A fase mais intensa costuma durar 2–4 dias ou noites; a tosse pode persistir mais. Reavalie antes se houver piora, febre persistente, aparência muito doente ou ausência de melhora no prazo combinado.','Evite contato próximo enquanto houver sintomas, lave as mãos, cubra tosse e espirros e mantenha a criança fora da escola enquanto estiver febril ou sem condições de participar.']
 ];
}
function clm(){return [
 ['Larva migrans cutânea costuma formar uma linha avermelhada, tortuosa e que coça, avançando lentamente na pele após contato com areia ou solo contaminado. Não esprema nem tente retirar a larva.','Mantenha a área limpa, unhas curtas e evite coçar para reduzir feridas e infecção bacteriana.'],
 ['Use compressa fria protegida por pano para aliviar coceira. Não aplique água sanitária, querosene, calor, ácidos, inseticida ou outras substâncias irritantes.','Use calçados ou barreira ao sentar em areia/solo e recolha fezes de cães e gatos; mantenha os animais com acompanhamento veterinário.'],
 ['Use somente antiparasitário ou remédio para coceira prescrito para a idade e o peso. Não invente dose, não compartilhe e não use produto veterinário.'],
 ['Mantenha alimentação e líquidos habituais. Não existe alimento capaz de eliminar a larva; evite restrições sem orientação.'],
 ['Procure atendimento sem demora se houver febre, pus, dor crescente, vermelhidão que se espalha, inchaço importante, lesão perto do olho ou genitais, falta de ar, chiado ou mal-estar geral.','Lesão profunda ou muito rápida, urticária que muda de lugar, sintomas digestivos ou respiratórios exigem reavaliação para outro diagnóstico, como estrongiloidíase.'],
 ['Reavalie se a lesão continuar avançando, surgirem novas trilhas, a coceira impedir o sono ou não houver melhora no prazo combinado. O tratamento costuma ser eficaz; sem tratamento, a evolução pode durar semanas.']
];}
function vlm(){return [
 ['Larva migrans visceral é uma infecção por larvas de Toxocara que podem migrar por órgãos, mais frequentemente fígado e pulmões. Algumas crianças não têm sintomas; outras podem apresentar febre, tosse, chiado, dor abdominal ou aumento do fígado.','Mantenha o acompanhamento e os exames definidos. Não presuma cura apenas porque a criança parece melhor.'],
 ['Lave as mãos após brincar com terra e antes de comer, mantenha unhas curtas e impeça ingestão de terra. Recolha fezes de cães e gatos e mantenha vermifugação veterinária.','Não deixe crianças brincarem em áreas contaminadas por fezes de animais; cubra caixas de areia quando não estiverem em uso.'],
 ['Use antiparasitário ou corticoide somente se prescritos, na dose e duração individualizadas. Não use produto veterinário nem repita tratamento por conta própria.'],
 ['Mantenha alimentação e líquidos conforme tolerância. Não há dieta que elimine as larvas; restrições só se houver outra indicação clínica.'],
 ['Falta de ar, chiado intenso, lábios arroxeados, dor no peito, desmaio, convulsão, fraqueza, confusão, dor abdominal forte, pele amarelada, febre persistente ou prostração exigem atendimento imediato.','Olho vermelho, dor ocular, pontos ou flashes na visão, desvio do olho ou perda de visão exigem avaliação oftalmológica urgente.'],
 ['Cumpra o retorno para revisar sintomas e exames; o prazo depende dos órgãos envolvidos e da resposta. Procure antes se surgirem sintomas respiratórios, neurológicos ou oculares.']
];}
function lta(){return [
 ['Leishmaniose tegumentar pode causar ferida na pele, muitas vezes pouco dolorosa, com bordas elevadas, e também atingir nariz, boca ou garganta. Precisa de confirmação e tratamento pela equipe; não é uma ferida comum para tratar sozinho.','Lave suavemente com água e sabonete, seque sem esfregar e proteja com gaze limpa se houver secreção ou atrito. Não cutuque nem retire crostas à força.'],
 ['Não cauterize, raspe, fure nem aplique ervas, ácidos, querosene ou produto veterinário. Essas medidas podem queimar, infectar e atrasar o diagnóstico.','Para reduzir novas picadas, use repelente adequado à idade, roupas compridas, telas finas e mosquiteiro, conforme orientação sanitária local.'],
 ['Use somente o tratamento prescrito e complete o esquema. A escolha depende da forma, localização, espécie/região, idade, peso e condições clínicas; esta ficha não fornece medicamento nem dose.','Avise a equipe sobre gravidez, doenças do coração, rins ou fígado e todos os medicamentos em uso. Não compartilhe sobras.'],
 ['Mantenha alimentação e líquidos habituais, salvo orientação diferente. Dor na boca ou garganta, dificuldade para engolir ou perda de peso precisam de reavaliação.'],
 ['Procure atendimento imediatamente se houver dificuldade para respirar ou engolir, sangramento importante, inchaço rápido, lesão perto do olho, febre com pus/vermelhidão crescente, prostração ou piora rápida.','Nariz entupido persistente, sangramento nasal, crostas ou feridas no nariz/boca, rouquidão, dor de garganta ou tosse persistente exigem avaliação rápida por possível acometimento mucoso.'],
 ['Cumpra os retornos durante e após o tratamento, mesmo que a ferida feche. Volte antes se a lesão aumentar, surgirem novas feridas, houver efeito adverso ou qualquer sintoma em nariz, boca ou garganta.','A transmissão habitual ocorre pela picada do inseto vetor, não pelo contato casual com a criança; ainda assim, mantenha a ferida limpa e coberta quando houver secreção.']
];}
